alter table public.transactions add column if not exists bank_code text;
create or replace function public.request_withdrawal(p_user uuid,p_amount numeric,p_card uuid)
returns uuid language plpgsql security definer set search_path=public as $$
declare w public.wallets%rowtype; c public.bank_accounts%rowtype; v_fee numeric; v_pct numeric; v_min numeric; v_max numeric; v_cap int; v_days text; v_start text; v_end text; v_tx uuid; v_used int; v_dow int; v_mins int; v_mode text;
begin
 select * into c from public.bank_accounts where id=p_card and user_id=p_user; if not found then raise exception 'Save a payout card before withdrawing.'; end if;
 if not exists(select 1 from public.leases where user_id=p_user and status='active') then raise exception 'You need at least one active lease to withdraw.'; end if;
 select coalesce(value::numeric,0) into v_min from public.settings where key='min_withdrawal'; select coalesce(value::numeric,0) into v_max from public.settings where key='max_withdrawal'; select coalesce(value::numeric,0) into v_pct from public.settings where key='withdrawal_fee'; select coalesce(value::int,1) into v_cap from public.settings where key='withdrawals_per_day'; select value into v_days from public.settings where key='withdrawal_days'; select value into v_start from public.settings where key='withdrawal_start'; select value into v_end from public.settings where key='withdrawal_end'; select case when value in('gateway','review','manual') then value else 'review' end into v_mode from public.settings where key='withdrawal_mode'; v_mode:=coalesce(v_mode,'review');
 if p_amount<v_min then raise exception 'Minimum withdrawal is %.',v_min; end if; if p_amount>v_max then raise exception 'Maximum withdrawal is %.',v_max; end if; select * into w from public.wallets where user_id=p_user for update; if p_amount>w.balance-w.locked then raise exception 'Insufficient available balance.'; end if;
 if exists(select 1 from public.transactions where user_id=p_user and type='withdrawal' and status='pending') then raise exception 'You already have a withdrawal awaiting review.'; end if; select count(*) into v_used from public.transactions where user_id=p_user and type='withdrawal' and status<>'rejected' and (created_at at time zone 'Africa/Lagos')::date=(now() at time zone 'Africa/Lagos')::date; if v_used>=v_cap then raise exception 'Daily limit reached — % withdrawals per day.',v_cap; end if;
 v_dow:=extract(dow from(now() at time zone 'Africa/Lagos'))::int; v_mins:=extract(hour from(now() at time zone 'Africa/Lagos'))::int*60+extract(minute from(now() at time zone 'Africa/Lagos'))::int; if position(v_dow::text in coalesce(v_days,''))=0 then raise exception 'Withdrawals are closed today. Allowed days: %.',v_days; end if; if v_mins<(split_part(v_start,':',1)::int*60+split_part(v_start,':',2)::int) or v_mins>=(split_part(v_end,':',1)::int*60+split_part(v_end,':',2)::int) then raise exception 'Withdrawals are closed. Window: % – % WAT.',v_start,v_end; end if;
 v_fee:=round(p_amount*v_pct/100,2); insert into public.transactions(user_id,type,amount,fee,net_amount,description,reference,status,bank_name,bank_code,account_number,account_name,processing_mode) values(p_user,'withdrawal',p_amount,v_fee,p_amount-v_fee,'Withdrawal to '||c.bank_name,'WTH-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,6)),'pending',c.bank_name,c.bank_code,c.account_number,c.account_name,v_mode) returning id into v_tx; update public.wallets set locked=locked+p_amount,updated_at=now() where user_id=p_user; return v_tx;
end $$;
revoke all on function public.request_withdrawal(uuid,numeric,uuid) from public,anon,authenticated;
grant execute on function public.request_withdrawal(uuid,numeric,uuid) to service_role;
